import re, json
p='src/game/specs.ts'
s=open(p).read()
def block(n):
    i=s.index(f"n: {n}, chapter:")
    j=s.find("\n  {\n    n: ", i+5)
    if j<0: j=s.index("\n];", i)
    return i,j
def set_field(n, field, val):
    global s
    i,j=block(n); b=s[i:j]
    lit=json.dumps(val, ensure_ascii=False)
    m=re.search(r'\n    '+field+r': "(?:[^"\\]|\\.)*",', b)
    if m:
        b=b[:m.start()]+f'\n    {field}: {lit},'+b[m.end():]
    else:
        k=b.index('\n    mechanics:')
        b=b[:k]+f'\n    {field}: {lit},'+b[k:]
    s=s[:i]+b+s[j:]
